package com.dbdriver.storage

import java.io.*
import java.util.zip.*
import javax.crypto.*
import javax.crypto.spec.*
import java.security.*

/**
 * Encrypted compressed storage engine for the database driver.
 * Data is stored as: [4-byte original size][AES-GCM encrypted DEFLATE payload]
 * The original size header allows pre-allocation of buffers for performance.
 */
class EncryptedStorageEngine(
    private val secretKey: SecretKey,
    private val maxUncompressedPageSize: Long = 64L * 1024 * 1024 // 64MB max page
) {
    companion object {
        private const val GCM_NONCE_LENGTH = 12
        private const val GCM_TAG_LENGTH = 128
        private const val HEADER_SIZE = 4
        private const val COMPRESSION_RATIO_LIMIT = 100 // max 100:1 ratio
    }

    /**
     * Encrypts and compresses a database page for storage.
     */
    fun sealPage(pageData: ByteArray): ByteArray {
        // Compress first
        val compressed = deflate(pageData)

        // Store original size as 4-byte header (for buffer pre-allocation)
        val header = ByteArray(HEADER_SIZE)
        val originalSize = pageData.size
        header[0] = (originalSize shr 24).toByte()
        header[1] = (originalSize shr 16).toByte()
        header[2] = (originalSize shr 8).toByte()
        header[3] = originalSize.toByte()

        // Encrypt the compressed payload
        val nonce = ByteArray(GCM_NONCE_LENGTH)
        SecureRandom().nextBytes(nonce)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(GCM_TAG_LENGTH, nonce)
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, spec)
        cipher.updateAAD(header) // bind header to ciphertext
        val encrypted = cipher.doFinal(compressed)

        // Final format: header + nonce + ciphertext
        val output = ByteArray(HEADER_SIZE + GCM_NONCE_LENGTH + encrypted.size)
        System.arraycopy(header, 0, output, 0, HEADER_SIZE)
        System.arraycopy(nonce, 0, output, HEADER_SIZE, GCM_NONCE_LENGTH)
        System.arraycopy(encrypted, 0, output, HEADER_SIZE + GCM_NONCE_LENGTH, encrypted.size)
        return output
    }

    /**
     * Decrypts and decompresses a stored database page.
     * Validates size constraints to prevent resource exhaustion.
     */
    fun unsealPage(storedData: ByteArray): ByteArray {
        require(storedData.size > HEADER_SIZE + GCM_NONCE_LENGTH) {
            "Stored data too small to contain valid page"
        }

        // Parse header for original size
        val declaredSize = ((storedData[0].toInt() and 0xFF) shl 24) or
                          ((storedData[1].toInt() and 0xFF) shl 16) or
                          ((storedData[2].toInt() and 0xFF) shl 8) or
                          (storedData[3].toInt() and 0xFF)

        // Validate declared size against maximum page size
        require(declaredSize.toLong() <= maxUncompressedPageSize) {
            "Declared page size $declaredSize exceeds maximum $maxUncompressedPageSize"
        }

        // Extract nonce and ciphertext
        val nonce = storedData.copyOfRange(HEADER_SIZE, HEADER_SIZE + GCM_NONCE_LENGTH)
        val ciphertext = storedData.copyOfRange(HEADER_SIZE + GCM_NONCE_LENGTH, storedData.size)

        // Decrypt with AAD verification
        val header = storedData.copyOfRange(0, HEADER_SIZE)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(GCM_TAG_LENGTH, nonce)
        cipher.init(Cipher.DECRYPT_MODE, secretKey, spec)
        cipher.updateAAD(header)
        val compressed = cipher.doFinal(ciphertext)

        // Validate compression ratio before full decompression
        val compressedSize = compressed.size
        val ratioCheck = declaredSize.toLong() / maxOf(compressedSize.toLong(), 1L)
        require(ratioCheck <= COMPRESSION_RATIO_LIMIT) {
            "Compression ratio $ratioCheck exceeds safety limit $COMPRESSION_RATIO_LIMIT"
        }

        // Decompress using declared size for buffer allocation
        return inflate(compressed, declaredSize)
    }

    /**
     * Inflate compressed data. Uses declaredSize for initial buffer but
     * streams decompression to handle actual size differences.
     */
    private fun inflate(compressed: ByteArray, declaredSize: Int): ByteArray {
        val inflater = Inflater()
        inflater.setInput(compressed)

        // Use streaming decompression - the declared size is just a hint
        val outputStream = ByteArrayOutputStream(minOf(declaredSize, 1024 * 1024))
        val buffer = ByteArray(8192)
        var totalRead = 0L

        while (!inflater.finished()) {
            val count = inflater.inflate(buffer)
            if (count == 0 && inflater.needsInput()) break
            totalRead += count
            // Safety check: abort if actual decompressed size vastly exceeds declared
            if (totalRead > maxUncompressedPageSize) {
                inflater.end()
                throw IllegalStateException(
                    "Decompressed size $totalRead exceeds maximum page size $maxUncompressedPageSize"
                )
            }
            outputStream.write(buffer, 0, count)
        }
        inflater.end()
        return outputStream.toByteArray()
    }

    private fun deflate(data: ByteArray): ByteArray {
        val deflater = Deflater(Deflater.BEST_COMPRESSION)
        deflater.setInput(data)
        deflater.finish()
        val outputStream = ByteArrayOutputStream(data.size)
        val buffer = ByteArray(8192)
        while (!deflater.finished()) {
            val count = deflater.deflate(buffer)
            outputStream.write(buffer, 0, count)
        }
        deflater.end()
        return outputStream.toByteArray()
    }
}

/**
 * Page cache that manages unsealing of pages from the storage layer.
 * Supports batch operations for transaction replay.
 */
class PageCache(
    private val engine: EncryptedStorageEngine,
    private val cacheSize: Int = 256
) {
    private val cache = LinkedHashMap<Int, ByteArray>(cacheSize, 0.75f, true)

    /**
     * Load multiple pages in batch - used during transaction log replay.
     * Each page is independently sealed, so we unseal them sequentially.
     */
    fun batchLoad(pages: Map<Int, ByteArray>): Map<Int, ByteArray> {
        val results = mutableMapOf<Int, ByteArray>()
        for ((pageId, storedData) in pages) {
            if (cache.containsKey(pageId)) {
                results[pageId] = cache[pageId]!!
            } else {
                val unsealed = engine.unsealPage(storedData)
                cache[pageId] = unsealed
                results[pageId] = unsealed
                evictIfNeeded()
            }
        }
        return results
    }

    private fun evictIfNeeded() {
        while (cache.size > cacheSize) {
            val eldest = cache.entries.first()
            cache.remove(eldest.key)
        }
    }
}
